const policyBasePremiumOf = (step: QuoteStep): number =>
  step.items.reduce((sum, item) => sum + basePremiumOf(item), 0);

/** Kept as an exact fraction — only the final premium is rounded. */
const premiumBeforeRounding = (step: QuoteStep): number => {
  const policyBasePremium = policyBasePremiumOf(step);
  const initialAssessmentSurcharge = policyBasePremium * INITIAL_ASSESSMENT_SURCHARGE_RATE;
  return policyBasePremium + initialAssessmentSurcharge + PROCESSING_FEE;
};

/** Rounded up, in the MHPCO's favour. */
const finalPremiumFor = (step: QuoteStep): number => Math.ceil(premiumBeforeRounding(step));

export const runScenario = (scenario: Scenario): ScenarioOutput => ({
  results: scenario.steps.map((step) => ({ premium: finalPremiumFor(step) })),
});
